// Check /opt/openmontage/projects for completed renders
const fs = require('fs');
const path = require('path');
const projectsDir = '/opt/openmontage/projects';

if (!fs.existsSync(projectsDir)) {
  return [{ renders: [], message: 'No projects directory' }];
}

const projects = fs.readdirSync(projectsDir, { withFileTypes: true })
  .filter(d => d.isDirectory())
  .map(d => d.name);

const renders = [];
for (const project of projects) {
  const outputDir = path.join(projectsDir, project, 'output');
  if (!fs.existsSync(outputDir)) continue;
  const files = fs.readdirSync(outputDir)
    .filter(f => f.match(/\.(mp4|webm|gif|png|jpg)$/i))
    .map(f => ({
      project,
      file: f,
      path: path.join(outputDir, f),
      mtime: fs.statSync(path.join(outputDir, f)).mtime.toISOString()
    }));
  renders.push(...files);
}

// Return only renders from last 5 minutes
const cutoff = Date.now() - 5 * 60 * 1000;
const recent = renders.filter(r => new Date(r.mtime).getTime() > cutoff);

return [{ renders: recent.length > 0 ? recent : [], count: renders.length, message: recent.length > 0 ? 'New renders found' : 'No new renders' }];

// Build publish notification
const renders = $input.all()[0].json.renders;
const summary = renders.map(r => `  - ${r.project}/${r.file}`).join('\n');

return [{
  action: 'publish',
  title: 'New OpenMontage renders ready for publishing',
  renders: renders,
  summary: summary,
  timestamp: new Date().toISOString()
}];
